-- Fakt kartochkalarining ruscha matni — 20-partiya:
-- Boborahim Mashrab, Muqimiy, Furqat.

-- ===== Boborahim Mashrab =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Бабарахим Машраб?', fact_ru = 'Я родился в 1640 году в Намангане.' WHERE id = 427;
UPDATE fact_cards SET topic_ru = 'Мой наставник', question_ru = 'У кого Бабарахим Машраб учился религиозным наукам и суфизму?', fact_ru = 'Религиозным наукам и суфизму я учился у Муллы Базара Ахунда, освоил и персидский язык.' WHERE id = 428;
UPDATE fact_cards SET topic_ru = 'На службе у Афак-Ходжи', question_ru = 'К кому на службу отправился Бабарахим Машраб?', fact_ru = 'Около 1665 года по совету моего наставника я отправился на службу к знаменитому духовному деятелю Афак-Ходже.' WHERE id = 429;
UPDATE fact_cards SET topic_ru = 'Моя поэзия', question_ru = 'Где создана большая часть стихов Бабарахима Машраба?', fact_ru = 'Большая часть моих стихов создана под влиянием суфизма, в обители Афак-Ходжи.' WHERE id = 430;
UPDATE fact_cards SET topic_ru = 'Мои странствия', question_ru = 'Как прошла жизнь Бабарахима Машраба?', fact_ru = 'Моя жизнь прошла в скитаниях из города в город, в дервишских странствиях.' WHERE id = 431;
UPDATE fact_cards SET topic_ru = 'В народе', question_ru = 'Как расходились стихи Бабарахима Машраба в народе?', fact_ru = 'Мои стихи широко расходились в народе, передаваясь из уст в уста.' WHERE id = 432;
UPDATE fact_cards SET topic_ru = 'Моё имя в тазкира', question_ru = 'В каких трудах упомянуто имя Бабарахима Машраба?', fact_ru = 'Моё имя упомянуто в тазкира, составленных в XVIII–XIX веках, и в трудах по суфизму.' WHERE id = 433;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Бабарахим Машраб?', fact_ru = 'Я скончался в 1711 году в городе Балх.' WHERE id = 434;
UPDATE fact_cards SET topic_ru = 'Мой псевдоним', question_ru = 'Каким именем звали Бабарахима Машраба в народе?', fact_ru = 'Моё настоящее имя — Бабарахим, а «Машраб» — мой псевдоним. В народе меня звали также «Дивана Машраб».' WHERE id = 1533;
UPDATE fact_cards SET topic_ru = 'Повесть «Диванаи Машраб»', question_ru = 'Как называется знаменитая народная повесть о жизни Бабарахима Машраба?', fact_ru = 'На основе моей жизни и моих стихов в народе была создана повесть под названием «Диванаи Машраб». Эта книга в рукописном виде широко разошлась по всей Средней Азии.' WHERE id = 1534;
UPDATE fact_cards SET topic_ru = 'Моя жизнь каландара', question_ru = 'Какой образ жизни избрал Бабарахим Машраб?', fact_ru = 'Свою жизнь я провёл просто и скромно, как дервиш-каландар. Я не гнался за богатством и чинами, а скитался по свету в поисках истины.' WHERE id = 1535;
UPDATE fact_cards SET topic_ru = 'Языки моих стихов', question_ru = 'На каких языках писал свои стихи Бабарахим Машраб?', fact_ru = 'Свои стихи я писал главным образом на тюркском (узбекском) языке, есть у меня стихи и на персидском.' WHERE id = 1536;
UPDATE fact_cards SET topic_ru = 'Мои мустазады', question_ru = 'В каких поэтических жанрах много творил Бабарахим Машраб?', fact_ru = 'Я много творил в жанрах газели и мустазада. Особенно прославились мои мустазады — их клали на музыку и пели.' WHERE id = 1537;
UPDATE fact_cards SET topic_ru = 'Мои обличительные стихи', question_ru = 'Что обличал Бабарахим Машраб в своих стихах?', fact_ru = 'В своих стихах я смело обличал лицемерие и несправедливость. За то, что я воспевал горе простого народа, меня читали с любовью.' WHERE id = 1538;
UPDATE fact_cards SET topic_ru = 'Моё имя сегодня', question_ru = 'Как вспоминают имя Бабарахима Машраба сегодня?', fact_ru = 'Сегодня в Узбекистане моим именем названы улицы, а мои стихи вновь и вновь издают отдельными книгами. Мои газели хафизы поют и поныне.' WHERE id = 1539;

-- ===== Muqimiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Мукими?', fact_ru = 'Я родился в 1850 году в городе Коканд. Моё настоящее имя — Мухаммад Аминходжа, сын Мирзаходжи, а «Мукими» — мой псевдоним. Отец мой был родом из Ташкента, мать Айшабиби — из Худжанда, а семья наша жила в Коканде.' WHERE id = 1916;
UPDATE fact_cards SET topic_ru = 'Моя мать и мои наставники', question_ru = 'Кто пробудил в Мукими любовь к поэзии и кого он считал своим наставником?', fact_ru = 'Любовь к поэзии пробудила во мне моя мать Айшабиби. Позже я учился на произведениях Навои, Джами, Низами и Физули, а Джами считал своим наставником.' WHERE id = 1917;
UPDATE fact_cards SET topic_ru = 'Годы моей учёбы', question_ru = 'В каких медресе учился Мукими?', fact_ru = 'Начальное образование я получил в школе нашей махалли. Затем учился в Коканде в медресе «Мохлар-ойим», построенном Надирой, а после — в бухарских медресе (в 1864–65 и 1875–76 годах).' WHERE id = 1918;
UPDATE fact_cards SET topic_ru = 'Моя служба писцом', question_ru = 'Где работал Мукими, вернувшись в Коканд в 1876 году?', fact_ru = 'В 1876 году я вернулся в Коканд и служил писцом в управе землеустройства. А с конца 1870-х годов я начал заниматься творчеством.' WHERE id = 1919;
UPDATE fact_cards SET topic_ru = 'Моя келья в «Хазрате»', question_ru = 'Куда и почему переселился Мукими в 1885 году?', fact_ru = 'После смерти отца моё положение стало тяжёлым, и в 1885 году я переселился в маленькую келью медресе «Хазрат». Вся моя жизнь прошла в бедности.' WHERE id = 1920;
UPDATE fact_cards SET topic_ru = 'Мои сатирические произведения', question_ru = 'Сколько сатирических произведений создал Мукими и кого он в них обличал?', fact_ru = 'Я создал около 30 сатирических произведений: среди них «Танабчилар», «Выборы», «В порицание времени», «Я безумец», «Я плешивый», «Мухи», «Жалоба на украшательство». В них я разоблачал проделки царских чиновников и местных богачей.' WHERE id = 1921;
UPDATE fact_cards SET topic_ru = 'Моё «Саёхатнаме»', question_ru = 'Как построено произведение Мукими «Саёхатнаме» и что в нём изображено?', fact_ru = 'Моё произведение «Саёхатнаме» состоит из 4 частей и написано лёгким, игривым размером, четверостишиями. В нём я реалистически изобразил тяжесть народной жизни и разорение селений.' WHERE id = 1922;
UPDATE fact_cards SET topic_ru = 'Мои поездки в Ташкент', question_ru = 'В какие годы Мукими ездил в Ташкент и с кем там сотрудничал?', fact_ru = 'В 1887–88 и в 1892 году я ездил в Ташкент. Там я основательно изучил культурную и литературную жизнь, завязал связи с такими передовыми по духу творцами, как Альмаи и Надим, и творчески сотрудничал с ними.' WHERE id = 1923;
UPDATE fact_cards SET topic_ru = 'Мои новые темы', question_ru = 'Какую новую тему внёс Мукими в узбекскую литературу?', fact_ru = 'В узбекскую литературу я внёс тему рабочих: я создал такие произведения, как «Об описании московского бая» и «Случай с Виктором». А в лирике я воспевал такие ценности, как дружба, верность и искренность — мои стихи проникнуты глубоким жизнелюбием.' WHERE id = 1924;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Мукими?', fact_ru = 'Я скончался 25 мая 1903 года в родном городе Коканде. Хотя вся моя жизнь прошла в бедности, творчества я не оставил до конца.' WHERE id = 1925;

-- ===== Furqat =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Фуркат?', fact_ru = 'Я родился в 1859 году в городе Коканд. Моё настоящее имя — Закирджан, сын Муллы Холмухаммада, а «Фуркат» — мой псевдоним.' WHERE id = 1926;
UPDATE fact_cards SET topic_ru = 'Моё образование', question_ru = 'В какие годы Фуркат учился в медресе?', fact_ru = 'Выучившись грамоте в школе нашей махалли, я изучил арабский язык и каллиграфию. В 1873–76 годах я учился в медресе.' WHERE id = 1927;
UPDATE fact_cards SET topic_ru = 'Школа Навои', question_ru = 'Творчество какого великого поэта основательно изучил Фуркат?', fact_ru = 'Я основательно изучил творчество Алишера Навои и наследие представителей персидской словесности, в совершенстве освоил персидский язык. Позже я слагал на произведения Навои назиры и тахмисы.' WHERE id = 1928;
UPDATE fact_cards SET topic_ru = 'В Новом Маргилане', question_ru = 'В какой город поехал Фуркат в 1876 году и каким делом занимался?', fact_ru = 'В 1876 году по просьбе моего дяди-купца я поехал в Новый Маргилан и помогал ему в торговых делах. Именно там я вполне сложился как творец и, подписывая свои газели псевдонимом «Фуркат», начал обретать известность.' WHERE id = 1929;
UPDATE fact_cards SET topic_ru = 'Ташкентские годы', question_ru = 'В какой город приехал Фуркат в 1889 году и в какой газете работал?', fact_ru = 'В июне 1889 года я приехал в Ташкент. Здесь я работал в «Туркистон вилоятининг газети» и печатал свои статьи.' WHERE id = 1930;
UPDATE fact_cards SET topic_ru = 'Проповедь просвещения', question_ru = 'Что проповедовал Фуркат в своих статьях?', fact_ru = 'В 1890-е годы я напечатал такие свои статьи, как «Польза знания», «Гимназия», «О выставке», «Суворов». В них я проповедовал новизну и развитие, науку и европейское образование и культуру.' WHERE id = 1931;
UPDATE fact_cards SET topic_ru = 'Мои произведения', question_ru = 'Какое произведение перевёл Фуркат с персидского языка?', fact_ru = 'Я написал трактат «Хаммоми хаёл», перевёл с персидского языка повесть «Четыре дервиша» и создал поэтическую книгу под названием «Нух манзар». По случаю моего паломничества в хадж я написал и произведение «Хаджнаме».' WHERE id = 1932;
UPDATE fact_cards SET topic_ru = 'Мой знаменитый мусаддас', question_ru = 'Какая мысль проводится в произведении Фурката «Отпусти свою добычу, охотник»?', fact_ru = 'В своём знаменитом мусаддасе «Отпусти свою добычу, охотник» я защищал право человека на вольную жизнь и решительно осуждал гнёт и произвол.' WHERE id = 1933;
UPDATE fact_cards SET topic_ru = 'Моё великое странствие', question_ru = 'Какие города и страны объехал Фуркат в странствии, начатом в 1891 году?', fact_ru = 'В июле 1891 года я через Мерв, Ашхабад, Баку и Батуми направился в Стамбул. В 1892 году я совершил паломничество в Мекку, Джидду и Медину, затем перебрался в Бомбей — в Индию, а в марте 1893 года через Кашмир и Тибет добрался до Восточного Туркестана.' WHERE id = 1934;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Где Фуркат провёл последние годы жизни и когда он умер?', fact_ru = 'С 1893 года и до конца жизни я оседло жил в городе Яркенд в Восточном Туркестане: занимался торговлей лекарственными травами, врачеванием и каллиграфией. Я скончался в 1909 году в Яркенде и погребён на кладбище Донгдор.' WHERE id = 1935;
